window.ForgeNotificationUI=(()=>{
const SETTINGS=[["browser_notifications","Device notifications"],["workout_reminders","Workout coming up"],["missed_workout_reminders","Missed workout"],["incomplete_workout_reminders","Incomplete workout"],["recovery_reminders","Recovery recommendation"],["deload_reminders","Deload starting / active"],["nutrition_reminders","Nutrition behind target"],["calendar_conflict_alerts","Calendar conflict"],["schedule_change_alerts","Workout schedule changes"],["morning_brief","Morning brief"]];
function center(d,settings,esc){
 const items=d?.items||[];
 return `<div class=row><div><p class=eyebrow>PROACTIVE COACHING</p><h2>Notifications</h2></div><span class=notification-count>${items.length}</span></div><p class=muted>Choose exactly which Forge reminders can reach you.</p><div class=spacer></div>${items.length?items.map(n=>`<div class="card notification-card ${n.priority}"><div><p class=eyebrow>${esc(n.type.replaceAll("_"," "))}</p><h3>${esc(n.title)}</h3><p class=muted>${esc(n.message)}</p>${n.action_prompt?`<button class="btn dark compact" data-notification-coach="${esc(n.action_prompt)}">Ask Coach</button>`:""}</div><button class=notification-dismiss data-notification-dismiss="${esc(n.key)}">×</button></div>`).join(""):`<div class=card><h3>You're caught up</h3><p class=muted>No proactive alerts right now.</p></div>`}<div class=big-spacer></div><div class=card><p class=eyebrow>SETTINGS</p><h3>Proactive Coaching</h3>${SETTINGS.map(([k,l])=>`<label class=notification-toggle><span>${l}</span><input type=checkbox data-notification-setting="${k}" ${settings?.[k]!==false?"checked":""}></label>`).join("")}<label class=notification-toggle><span>Reminder lead time</span><select id=notificationLead>${[[30,"30 min"],[60,"1 hour"],[90,"90 min"],[120,"2 hours"]].map(([v,l])=>`<option value=${v} ${Number(settings?.reminder_minutes_before||90)===v?"selected":""}>${l}</option>`).join("")}</select></label></div>`;
}
return {center};
})();